/**
 * @file    MiniGameAudioBackend.ts
 * @brief   Audio for the mini-game platform family — one player per sound over
 *          the host's `createInnerAudioContext()`.
 *
 *          Written against the normalized {@link MiniGameInnerAudioContext}, not
 *          `wx`, so every vendor of the family gets it without an implementation
 *          of its own. There is no mixer: mini-game hosts expose finished
 *          players, not a DSP graph, so routing labels are honored by the engine
 *          and the graph itself is absent (`mixer` is null by contract).
 */

declare class MiniGameAudioBackend implements PlatformAudioBackend {
    readonly name: string;
    readonly delivery: "url";
    private readonly g_;
    private contexts_;
    private readonly device_;
    private urlCache_;
    /** The silence encoding put before a clip the exporter re-encoded, by buffer: a player is started past it. */
    private leads_;
    private nextId_;
    constructor(global: MiniGameGlobal, label?: string);
    get mixer(): AudioMixer | null;
    get isReady(): boolean;
    initialize(_options?: AudioBackendInitOptions): Promise<void>;
    ensureResumed(): Promise<void>;
    loadBuffer(src: string, options?: AudioLoadOptions): Promise<AudioBufferHandle>;
    /** No decoder here — the player streams from `src`, and the bytes are dropped.
     *  Callers avoid the wasted fetch by reading {@link delivery} first. */
    loadBufferFromData(src: string, _data: ArrayBuffer, options?: AudioLoadOptions): Promise<AudioBufferHandle>;
    unloadBuffer(handle: AudioBufferHandle): void;
    play(buffer: AudioBufferHandle, config: PlayConfig): AudioHandle;
    suspend(): void;
    resume(): void;
    dispose(): void;
}

/**
 * Install `profile`'s platform as the process-wide one and return its adapter.
 *
 * `adapter` lets a vendor that already built one (to export it by name) install
 * THAT instance — the adapter holds per-host state (the filesystem manager, the
 * input bindings), so a second instance would split it.
 *
 * Polyfills are applied once per vendor: a game that boots twice (a devtools
 * reload) does not re-polyfill, but re-installs the platform.
 */
declare function installMiniGamePlatform(profile: MiniGameProfile, adapter?: MiniGamePlatformAdapter): MiniGamePlatformAdapter;

export { AudioBackendInitOptions, AudioBufferHandle, AudioHandle, AudioMixer, MiniGameAudioBackend, MiniGameGlobal, MiniGamePlatformAdapter, MiniGameProfile, PlatformAudioBackend, PlayConfig, installMiniGamePlatform };
